func TestGeneratedObservationMetadata(t *testing.T) {
	codecs, err := codecs()
	if err != nil {
		t.Fatal(err)
	}
	support, _, err := codecs.Support.Decode(json.RawMessage("{\n        \"state\": {},\n        \"operations\": {}\n      }"))
	if err != nil {
		t.Fatalf("support: %v", err)
	}
	state, _, err := codecs.State.Decode(json.RawMessage("{\n            \"periods\": [\n              {\n                \"starts_at\": \"2026-11-09T19:00:00Z\",\n                \"temperature\": 0,\n                \"humidity\": 0,\n                \"precipitation_probability\": 0\n              }\n            ]\n          }"))
	if err != nil {
		t.Fatalf("State: %v", err)
	}
	receivedAt := time.Date(2026, time.March, 10, 14, 30, 0,
		123456789, time.FixedZone("CET", 3600))
	observation, err := NewObservation(ObservationInput{EntityID: "ent_01890f47-7a6b-7c4d-8e9f-0123456789ab", Support: support, State: state, AdapterReceivedAt: receivedAt})
	if err != nil {
		t.Fatalf("observation: %v", err)
	}
	if observation.EntityID != "ent_01890f47-7a6b-7c4d-8e9f-0123456789ab" {
		t.Errorf("observation entity ID = %q", observation.EntityID)
	}
	if entitytypetest.CanonicalJSON(t, observation.Value) != entitytypetest.CanonicalJSON(t, json.RawMessage("{\n            \"periods\": [\n              {\n                \"starts_at\": \"2026-11-09T19:00:00Z\",\n                \"temperature\": 0,\n                \"humidity\": 0,\n                \"precipitation_probability\": 0\n              }\n            ]\n          }")) {
		t.Errorf("observation value = %s", observation.Value)
	}
	if received := adaptertest.ParseAdapterTime(t, "adapter received time", observation.AdapterReceivedAt); !received.Equal(receivedAt) {
		t.Errorf("adapter received time = %s, want %s", observation.AdapterReceivedAt, receivedAt.UTC().Format(time.RFC3339Nano))
	}
	if observation.SourceUpdatedAt != nil {
		t.Errorf("observation without source time carries SourceUpdatedAt = %s", *observation.SourceUpdatedAt)
	}
	sourceAt := time.Date(2026, time.March, 9, 8, 15, 30, 0, time.FixedZone("EST", -5*3600))
	sourced, err := NewObservation(ObservationInput{EntityID: "ent_01890f47-7a6b-7c4d-8e9f-0123456789ab", Support: support, State: state, AdapterReceivedAt: receivedAt, SourceUpdatedAt: &sourceAt})
	if err != nil {
		t.Fatalf("sourced observation: %v", err)
	}
	if sourced.SourceUpdatedAt == nil {
		t.Fatal("observation with source time has no SourceUpdatedAt")
	}
	if updated := adaptertest.ParseAdapterTime(t, "source updated time", *sourced.SourceUpdatedAt); !updated.Equal(sourceAt) {
		t.Errorf("source updated time = %s, want %s", *sourced.SourceUpdatedAt, sourceAt.UTC().Format(time.RFC3339Nano))
	}
}

func TestGeneratedObservationValidation(t *testing.T) {
	codecs, err := codecs()
	if err != nil {
		t.Fatal(err)
	}
	support, _, err := codecs.Support.Decode(json.RawMessage("{\n        \"state\": {},\n        \"operations\": {}\n      }"))
	if err != nil {
		t.Fatalf("support: %v", err)
	}
	state, _, err := codecs.State.Decode(json.RawMessage("{\n            \"periods\": [\n              {\n                \"starts_at\": \"2026-11-09T19:00:00Z\",\n                \"temperature\": 0,\n                \"humidity\": 0,\n                \"precipitation_probability\": 0\n              }\n            ]\n          }"))
	if err != nil {
		t.Fatalf("State: %v", err)
	}
	receivedAt := time.Date(2026, time.March, 10, 14, 30, 0, 0, time.UTC)
	if _, err := NewObservation(ObservationInput{Support: support, State: state, AdapterReceivedAt: receivedAt}); err == nil {
		t.Error("Observation without entity ID was accepted")
	} else {
		adaptertest.RequireValidationError(t, err, "reject empty entity ID")
	}
	if _, err := NewObservation(ObservationInput{EntityID: "ent_01890f47-7a6b-7c4d-8e9f-0123456789ab", Support: support, State: state}); err == nil {
		t.Error("Observation without adapter received time was accepted")
	} else {
		adaptertest.RequireValidationError(t, err, "reject zero adapter received time")
	}
	zeroSource := time.Time{}
	if _, err := NewObservation(ObservationInput{EntityID: "ent_01890f47-7a6b-7c4d-8e9f-0123456789ab", Support: support, State: state, AdapterReceivedAt: receivedAt, SourceUpdatedAt: &zeroSource}); err == nil {
		t.Error("Observation with zero source updated time was accepted")
	} else {
		adaptertest.RequireValidationError(t, err, "reject zero source updated time")
	}
}

func TestGeneratedEntityDescriptor(t *testing.T) {
	codecs, err := codecs()
	if err != nil {
		t.Fatal(err)
	}
	support, _, err := codecs.Support.Decode(json.RawMessage("{\n        \"state\": {},\n        \"operations\": {}\n      }"))
	if err != nil {
		t.Fatalf("support: %v", err)
	}
	metadata := adapter.EntityMetadata{Key: "key_01890f47-7a6b-7c4d-8e9f-0123456789ab", ExternalID: "ext-001", Name: "generated entity"}
	descriptor, err := NewEntityDescriptor(metadata, support)
	if err != nil {
		t.Fatalf("descriptor: %v", err)
	}
	if descriptor.Key != metadata.Key {
		t.Errorf("descriptor key = %q", descriptor.Key)
	}
	if descriptor.ExternalID != metadata.ExternalID {
		t.Errorf("descriptor external ID = %q", descriptor.ExternalID)
	}
	if descriptor.Name != metadata.Name {
		t.Errorf("descriptor name = %q", descriptor.Name)
	}
	if descriptor.Type != "hearth.hourlyforecast/v1" {
		t.Errorf("descriptor type = %q", descriptor.Type)
	}
	if entitytypetest.CanonicalJSON(t, descriptor.Support) != entitytypetest.CanonicalJSON(t, json.RawMessage("{\n        \"state\": {},\n        \"operations\": {}\n      }")) {
		t.Errorf("descriptor support = %s", descriptor.Support)
	}
}
